pub const ERROR_NATIVE_BINDINGS: NativeBindingSet = NativeBindingSet {
    name: "error",
    bindings: &[NativeBinding::new(
        ERROR_ERROR_TAKE_PLATFORM_ERROR,
        "destack.error.error.takePlatformError",
        destack_error_error_take_platform_error as *const (),
    )],
};

/// Native export wrappers for error bindings.
#[unsafe(export_name = "destack.error.error.takePlatformError")]
pub unsafe extern "C" fn destack_error_error_take_platform_error(
    out: *mut platform_error::PlatformError,
    errorid: u64,
) -> RuntimeStatus {
    native_call(|context| {
        if out.is_null() {
            return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
        }
        let _ = (&out, &errorid);

        {
            let _binding_hook_guard = context.on_before_binding(ERROR_ERROR_TAKE_PLATFORM_ERROR)?;
            unsafe {
                platform_runtime_native::destack_error_take_platform_error(context, out, errorid)
            }
        }
    })
}

/// Register VM bindings for error.
pub fn register_error_vm_bindings(registry: &mut BindingRegistry, isolate: &mut Isolate) {
    {
        binding!(
            registry,
            isolate,
            ERROR_ERROR_TAKE_PLATFORM_ERROR,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (errorid,) =
                        decode_destack_error_error_take_platform_error_args(context, args)?;

                    // execute binding
                    let result = {
                        let _binding_hook_guard =
                            binding.on_before_binding(ERROR_ERROR_TAKE_PLATFORM_ERROR)?;
                        platform_runtime_vm::destack_error_take_platform_error(
                            binding, context, errorid,
                        )
                    };
                    encode_destack_error_error_take_platform_error_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
}

/// Install VM bindings for error.
pub fn install_error_vm_bindings(registry: &mut BindingRegistry, isolate: &mut Isolate) {
    register_error_vm_bindings(registry, isolate);
}

vm_binding_set!(pub ERROR_VM_BINDINGS, "error", install_error_vm_bindings);
